function findAdTargets(observation) {
  if (observation.truncated || observation.nodes.some(n=>n.textTruncated)) return [];
  const nodes=observation.nodes;
  const candidates=nodes.filter(n=>n.visible!==false && n.enabled && n.clickTarget && /^(?:跳过(?:广告|\s*\d{1,2}\s*[sS秒]?)?|\d{1,2}\s*[sS秒]?\s*跳过)$/.test((n.text||n.description||'').trim()));
  return [...new Set(candidates.filter(n=>nodes.some(ad=>ad.visible!==false && (ad.text||'').trim()==='广告' && ad.id!==n.id && ad.id!==n.clickTarget && (!ad.clickTarget || ad.clickTarget!==n.clickTarget))).map(n=>n.clickTarget))];
}

