let busy=false, lastAttempt=0;
(async()=>{
  const script=document.createElement('script');script.src='/match.js';
  await new Promise((resolve,reject)=>{script.onload=resolve;script.onerror=reject;document.head.append(script);});
  await dshx.ready;
  dshx.screen.onChange(async()=>{
    if(busy || Date.now()-lastAttempt<5000)return;
    busy=true;
    try {
      const observation=await dshx.screen.observe();
      const targets=findAdTargets(observation);
      if(targets.length!==1)return;
      lastAttempt=Date.now();
      const result=await dshx.screen.click(observation.snapshot,targets[0]);
      await dshx.storage.set('lastResult',result.ok?'点击已返回，等待后续界面确认':'点击失败，未重试');
    } catch(e) { await dshx.storage.set('lastResult',e.message).catch(()=>{}); }
    finally {busy=false;}
  });
})();
